# Relative links also work under a GitHub Pages repository subpath.
for html in D.rglob("*.html"):
    if ".git" in html.parts: continue
    depth=len(html.relative_to(D).parts)-1
    prefix="../"*depth or "./"
    text=html.read_text()
    text=re.sub(r'(\b(?:href|src|data-enlarge)=")/(?!/)', lambda m:m.group(1)+prefix,text)
    html.write_text(text)
